from src.nodes.base import BaseNode
from src.runtime.assets.acquisition_online import get_download_queue

class Hou_Mcp_Download_Queue(BaseNode):
    name = "hou_mcp_download_queue"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",   "string", widget_type="text", default="status")
        self.add_input("asset_id", "string", widget_type="text")
        self.add_input("provider", "string", widget_type="text", default="megascans")
        self.add_input("task_id",  "string", widget_type="text")
        self.add_input("priority", "int",    widget_type="int",  default=5)
        self.add_input("quality",  "string", widget_type="text", default="medium")
        self.add_input("dest_dir", "string", widget_type="text")
        self.add_output("task",    "any")
        self.add_output("tasks",   "list")
        self.add_output("stats",   "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action   = str(inputs.get("action") or "status").strip().lower()
        asset_id = str(inputs.get("asset_id") or "").strip()
        provider = str(inputs.get("provider") or "megascans").strip()
        task_id  = str(inputs.get("task_id") or "").strip()
        priority = int(inputs.get("priority") or 5)
        quality  = str(inputs.get("quality") or "medium").strip()
        dest_dir = str(inputs.get("dest_dir") or "").strip()
        try:
            q = get_download_queue()
            if action == "enqueue":
                t = q.enqueue(asset_id, provider=provider, quality=quality, dest_dir=dest_dir, priority=priority)
                return {"task": t.to_dict(), "tasks": [], "stats": q.get_statistics(), "exec_out": True}
            elif action == "dequeue":
                t = q.dequeue()
                return {"task": t.to_dict() if t else {}, "tasks": [], "stats": q.get_statistics(), "exec_out": True}
            elif action == "cancel":
                q.cancel(task_id)
                return {"task": {}, "tasks": [], "stats": q.get_statistics(), "exec_out": True}
            elif action == "retry":
                q.retry(task_id)
                return {"task": {}, "tasks": [], "stats": q.get_statistics(), "exec_out": True}
            elif action == "pending":
                tasks = q.get_pending()
                return {"task": {}, "tasks": [t.to_dict() for t in tasks], "stats": q.get_statistics(), "exec_out": True}
            elif action == "all":
                tasks = q.get_all()
                return {"task": {}, "tasks": [t.to_dict() for t in tasks], "stats": q.get_statistics(), "exec_out": True}
            elif action == "clear_completed":
                n = q.clear_completed()
                return {"task": {"cleared": n}, "tasks": [], "stats": q.get_statistics(), "exec_out": True}
            else:
                t = q.get_status(task_id)
                return {"task": t.to_dict() if t else {}, "tasks": [], "stats": q.get_statistics(), "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_download_queue failed: {e}")
            return {"task": {}, "tasks": [], "stats": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Download_Queue
